    // ============================================================
    // Root lookup
    //
    // Python:
    //     w = roots_dict_Zq[n]
    //     w[index]
    //
    // SystemVerilog:
    //     w = get_root(n, index)
    //
    // Supported n:
    //     2, 4, 8, 16, 32, 64, 128, 256, 512, 1024
    // ============================================================

    function automatic logic [WIDTH-1:0] get_root (
        input int n,
        input int index
    );
        begin
            case (n)
                2: get_root = ROOTS_2[index];
                4: get_root = ROOTS_4[index];
                8: get_root = ROOTS_8[index];
                16: get_root = ROOTS_16[index];
                32: get_root = ROOTS_32[index];
                64: get_root = ROOTS_64[index];
                128: get_root = ROOTS_128[index];
                256: get_root = ROOTS_256[index];
                512: get_root = ROOTS_512[index];
                1024: get_root = ROOTS_1024[index];
                default: get_root = '0;
            endcase
        end
    endfunction

    // ============================================================
    // Inverse lookup
    //
    // Python:
    //     inv_mod_q[x]
    //
    // SystemVerilog:
    //     get_inv(x)
    // ============================================================

    function automatic logic [WIDTH-1:0] get_inv (
        input int index
    );
        begin
            get_inv = INV_MOD_Q[index];
        end
    endfunction

